### Alternative Implementation

```rust
fn find_first_codon(record: &BedRecord) -> Option<Codon> {
    let mut exon = 0;
    let cds_start = max(record.cds_start(), record.exon_start()[exon]);

    for exon_frame in record.get_exon_frames() {
        let cds_frame = if record.strand() == "+" { exon_frame } else { (exon_frame + (cds_start - record.cds_start())) % 3 };
        if cds_frame == 0 {
            let cds_end = min(record.cds_end(), cds_start + 3);
            return Some(Codon {
                start: cds_start,
                end: cds_end,
                index: exon as u32,
                ..Codon::new() // Copy default values for start2 and end2
            });
        }
        if cds_frame < 0 {
            return None; // No valid CDS frame found
        }
        exon += 1;
    }

    None // If no valid codon found, return None
}
```

